function findPatternLocations(content2, pattern) {
  const lines = content2.split("\n");
  const locations = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i] ?? "";
    if (pattern.test(line)) {
      pattern.lastIndex = 0;
      const lineNum = i + 1;
      const preview = line.trim().slice(0, 50);
      locations.push(`Line ${lineNum}: "${preview}..."`);
    }
  }
  return locations;
}
